const DB_NAME = 'amanah_guard_db';
const DB_VERSION = 1;
const STORE = 'state';
const DEFAULT_STATE = {
  settings: {
    organization: 'مؤسسة الأمانة',
    lastBackupAt: null, schema: 2,
    attendancePaid: { حاضر: true, غياب: false, إجازة: false, مرضية: false, عطلة: false }
  },
  companies: [
    { id:'maven', name:'مايفين', monthlyRevenue:35520, taxRate:11, taxBasis:'net', active:true, partners:[] },
    { id:'ewan', name:'ايوان', monthlyRevenue:18000, taxRate:0, taxBasis:'gross', active:true, partners:[] }
  ],
  employees: [],
  attendance: {},
  loans: [],
  cash: [],
  expenses: [],
  revenues: [],
  transfers: [],
  partnerPayments: [],
  partnerAdjustments: [],
  payroll: {},
  settlements: {},
  audit: []
};
let state = normalizeState({});
let currentRoute = 'dashboard';
let currentCompany = 'all';
const sel = { att:null, pay:null, settle:null };

const navItems = [
  ['dashboard','⌂','لوحة التحكم'],
  ['companies','🏢','الشركات'],
  ['employees','👥','الموظفون'],
  ['attendance','✓','الحضور'],
  ['payroll','▣','المرتبات'],
  ['loans','↔','السلف'],
  ['cash','▤','الخزينة'],
  ['settlements','٪','التسويات'],
  ['reports','▥','التقارير'],
  ['settings','⚙','الإعدادات']
];

function clone(x){return JSON.parse(JSON.stringify(x));}
function normalizeState(p){
  const d=clone(DEFAULT_STATE);const s={...d,...p};const oldSchema=Object.keys(p).length?((p.settings&&p.settings.schema)||1):2;
  s.settings={...d.settings,...(p.settings||{}),attendancePaid:{...d.settings.attendancePaid,...((p.settings&&p.settings.attendancePaid)||{})}};
  ['companies','employees','loans','cash','expenses','revenues','transfers','partnerPayments','partnerAdjustments','audit'].forEach(k=>{if(!Array.isArray(s[k]))s[k]=clone(d[k])});
  ['attendance','payroll','settlements'].forEach(k=>{if(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k]))s[k]={}});
  if(oldSchema<2){
    s.companies.forEach(c=>{if(c.id==='maven'&&c.taxBasis==='gross'&&Number(c.taxRate)===11)c.taxBasis='net'});
    s.cash.forEach(x=>{if(!x.ref&&/^(LOAN|REV|EXP|TR|PP|PAY)-/.test(x.note||'')){x.ref=x.note;x.note=''}});
    s.settings.schema=2;
  }
  return s;
}
let serverRev=0,saving=false,dirty=false,saveTimer=null,pollTimer=null,restoreNext=false,lastSnap='',pendingAudit=[];
const snap=()=>JSON.stringify({...state,audit:0});
function setSync(kind,msg){const el=document.getElementById('syncBadge');if(el){el.className='sync-badge '+kind;el.textContent=msg}}
function saveState(opts){if(opts&&opts.restore)restoreNext=true;dirty=true;setSync('busy','جارٍ الحفظ…');clearTimeout(saveTimer);saveTimer=setTimeout(flushSave,250);renderBackupBadge()}
async function flushSave(){saveTimer=null;if(saving||!dirty)return;saving=true;dirty=false;const restore=restoreNext;restoreNext=false;const sent=snap(),onlyAudit=sent===lastSnap,n=pendingAudit.length;
 try{const r=await Auth.api('PUT','/api/state',{baseRev:serverRev,state,restore});
  if(r.status===200){serverRev=r.data.rev;lastSnap=sent;pendingAudit.splice(0,n);if(!dirty)setSync('ok','✓ محفوظ على الخادم')}
  else if(r.status===409){if(onlyAudit){const mine=pendingAudit.splice(0);await reloadFromServer();mine.forEach(a=>{if(!state.audit.some(x=>x.id===a.id))state.audit.push(a)});dirty=true}else{dirty=false;pendingAudit=[];await reloadFromServer();showToast('تعدّلت البيانات من مستخدم آخر؛ حُمّلت آخر نسخة. كرّر آخر عملية إن لزم.');setSync('ok','✓ محدَّث')}}
  else if(r.status===401){dirty=false}
  else if(r.status===403){dirty=false;await reloadFromServer();showToast((r.data&&r.data.error)||'لا تملك صلاحية الحفظ')}
  else{dirty=true;if(restore)restoreNext=true;setSync('err','تعذر الحفظ — إعادة المحاولة…');if(!saveTimer)saveTimer=setTimeout(flushSave,4000)}
 }finally{saving=false;if(dirty&&!saveTimer)saveTimer=setTimeout(flushSave,100)}}
async function flushNow(){clearTimeout(saveTimer);saveTimer=null;for(let i=0;i<40&&(saving||dirty);i++){if(!saving)await flushSave();else await new Promise(r=>setTimeout(r,100))}}
async function reloadFromServer(){const r=await Auth.api('GET','/api/state');if(r.status!==200){setSync('err','تعذر تحميل البيانات');return false}state=normalizeState(r.data.state||{});serverRev=r.data.rev;lastSnap=snap();refreshCompanyFilter();render();setSync('ok','✓ محفوظ على الخادم');return true}
async function pollServer(){if(!Auth.current()||saving||dirty)return;const r=await Auth.api('GET','/api/rev');if(r.status===0){setSync('err','لا يوجد اتصال بالخادم');return}if(r.status!==200)return;if(r.data.rev!==serverRev){const ae=document.activeElement;if(document.querySelector('.modal-backdrop')||(ae&&/^(INPUT|SELECT|TEXTAREA)$/.test(ae.tagName)&&document.getElementById('content').contains(ae)))return;if(await reloadFromServer())showToast('تم تحديث البيانات'+(r.data.by?` (بواسطة ${r.data.by})`:''))}else if(document.getElementById('syncBadge')&&/err/.test(document.getElementById('syncBadge').className))setSync('ok','✓ متصل بالخادم')}
function startPolling(){stopPolling();pollTimer=setInterval(pollServer,4000);window.addEventListener('focus',pollServer)}
function stopPolling(){clearInterval(pollTimer);pollTimer=null;window.removeEventListener('focus',pollServer)}
window.addEventListener('beforeunload',e=>{if(dirty||saving){e.preventDefault();e.returnValue=''}});
function uid(prefix='ID'){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);}
function fmt(n){return `${Number(n||0).toLocaleString('ar-EG',{maximumFractionDigits:2})} ج`}
function num(v){return Number(v)||0}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function companyName(id){return state.companies.find(c=>c.id===id)?.name||'—'}
function monthKey(y,m){return `${y}-${String(m).padStart(2,'0')}`}
function currentMonth(){const d=new Date();return {y:d.getFullYear(),m:d.getMonth()+1}}
function daysInMonth(y,m){return new Date(y,m,0).getDate()}
function showToast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
function audit(action,meta={}){{const a={id:uid('AUD'),at:new Date().toISOString(),by:(Auth.current()||{}).username||null,action,meta};state.audit.push(a);pendingAudit.push(a)} if(state.audit.length>1000)state.audit.shift();}

function today(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function nextMonthKey(mk){const [y,m]=mk.split('-').map(Number);return m===12?monthKey(y+1,1):monthKey(y,m+1)}
function empsForMonth(mk,co='all'){return state.employees.filter(e=>(co==='all'||e.companyId===co)&&(e.active||Object.keys((state.attendance[mk]||{})[e.id]||{}).length>0||Boolean(((state.payroll[mk]||{}).items||{})[e.id]?.paid)))}
function nameSig(s){return String(s||'').replace(/[\u064B-\u0652\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').trim().split(/\s+/).sort().join(' ')}
function dupEmployee(name,no,companyId,exceptId){const sig=nameSig(name);const d=state.employees.find(e=>e.id!==exceptId&&e.companyId===companyId&&(nameSig(e.name)===sig||(no&&e.employeeNo&&e.employeeNo===no)));return d?`يوجد موظف بنفس الاسم أو الرقم الوظيفي في نفس الشركة: ${d.name}`:null}
function refreshCompanyFilter(){const el=document.getElementById('companyFilter');const cur=currentCompany;el.innerHTML=`<option value="all">كل الشركات</option>`+state.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');el.value=state.companies.some(c=>c.id===cur)?cur:'all'}
function buildNav(){const items=[...navItems,...(Auth.can('users')?[['users','🔑','المستخدمون']]:[])];document.getElementById('nav').innerHTML=items.map(([id,icon,label])=>`<button class="nav-btn" data-route="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')}
function renderUserBox(){const u=Auth.current();const el=document.getElementById('userBox');if(!u){el.innerHTML='';return}el.innerHTML=`<div class="user-name">${esc(u.name)}</div><div class="user-role">${esc(Auth.ROLES[u.role]||u.role)}</div><div class="user-actions"><button class="btn small ghost" data-action="change-password">كلمة المرور</button><button class="btn small ghost" data-action="logout">خروج</button></div>`}
function init(){
  buildNav();
  refreshCompanyFilter();
  document.getElementById('userBox').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='change-password')return changePasswordModal();if(b.dataset.action==='logout'){audit('تسجيل خروج');saveState();flushNow().then(()=>Auth.logout());}});
  document.getElementById('companyFilter').addEventListener('change',e=>{currentCompany=e.target.value;render();});
  document.getElementById('quickBackup').addEventListener('click',backup);
  document.getElementById('menuBtn').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));
  document.getElementById('nav').addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b){currentRoute=b.dataset.route;document.querySelector('.sidebar').classList.remove('open');render();}});
  document.getElementById('content').addEventListener('click',handleClick);
  render();
}

function render(){
  if(!Auth.current())return;
  if(currentRoute==='users'&&!Auth.can('users'))currentRoute='dashboard';
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.route===currentRoute));
  const titles={users:['المستخدمون','إدارة الحسابات والصلاحيات'],dashboard:['لوحة التحكم','إدارة مايفين وايوان من مكان واحد'],companies:['الشركات','إعدادات ومعلومات كل شركة'],employees:['الموظفون','سجل موحد للموظفين وربطهم بالشركة'],attendance:['الحضور','تسجيل الحضور اليومي وحساب الأيام المستحقة'],payroll:['المرتبات','كشف المرتبات الشهري التلقائي'],loans:['السلف','سلف الموظفين والتحويلات بين الشركتين'],cash:['الخزينة','الإيرادات والمنصرف والرصيد'],settlements:['التسويات','الضريبة وصافي الربح ونصيب الشركاء'],reports:['التقارير','طباعة وتصدير التقارير'],settings:['الإعدادات','إعدادات النظام والنسخ الاحتياطي']};
  document.getElementById('pageTitle').textContent=titles[currentRoute][0];document.getElementById('pageSubtitle').textContent=titles[currentRoute][1];
  const c=document.getElementById('content');
  if(currentRoute==='users')renderUsers(c); else if(currentRoute==='dashboard')renderDashboard(c); else if(currentRoute==='companies')renderCompanies(c); else if(currentRoute==='employees')renderEmployees(c); else if(currentRoute==='attendance')renderAttendance(c); else if(currentRoute==='payroll')renderPayroll(c); else if(currentRoute==='loans')renderLoans(c); else if(currentRoute==='cash')renderCash(c); else if(currentRoute==='settlements')renderSettlements(c); else if(currentRoute==='reports')renderReports(c); else renderSettings(c);
  renderUserBox();renderBackupBadge();
}

function renderDashboard(c){
  c.innerHTML=document.getElementById('dashboardTemplate').innerHTML;
  const cashByCompany=Object.fromEntries(state.companies.map(co=>[co.id,calcCash(co.id)]));
  document.getElementById('statMavenCash').textContent=fmt(cashByCompany.maven||0);
  document.getElementById('statEwanCash').textContent=fmt(cashByCompany.ewan||0);
  document.getElementById('statPayroll').textContent=fmt(Object.keys(state.payroll).filter(k=>state.payroll[k].approvedAt).reduce((t,k)=>t+empsForMonth(k).reduce((a,e)=>a+calcPayroll(e,k).net,0),0));
  document.getElementById('statLoans').textContent=fmt(state.loans.reduce((s,l)=>s+Math.max(0,num(l.amount)-num(l.repaid)),0));
  document.getElementById('companySummary').innerHTML=state.companies.map(co=>{const st=calcSummary(co.id,currentMonth());return `<div class="company-row"><div class="company-meta"><span class="dot ${co.active?'green':''}"></span><div><b>${esc(co.name)}</b><div class="muted">إيراد شهري ${fmt(co.monthlyRevenue)} — رصيد الخزينة ${fmt(calcCash(co.id))}</div></div></div><div class="amount">ربح ${fmt(st.profit)}</div></div>`}).join('');
  const alerts=[];if(!state.settings.lastBackupAt)alerts.push('لم يتم إنشاء نسخة احتياطية حتى الآن.');else if(Date.now()-new Date(state.settings.lastBackupAt).getTime()>7*86400000)alerts.push('مر أكثر من أسبوع على آخر نسخة احتياطية.');
  state.companies.forEach(co=>{const unpaid=state.loans.filter(l=>l.companyId===co.id).reduce((s,l)=>s+Math.max(0,num(l.amount)-num(l.repaid)),0);if(unpaid>0)alerts.push(`${co.name}: سلف قائمة بقيمة ${fmt(unpaid)}.`)});
  document.getElementById('alerts').innerHTML=alerts.length?alerts.map(x=>`<div class="alert-row"><span class="alert-icon">!</span><span>${esc(x)}</span></div>`).join(''):`<div class="empty">لا توجد تنبيهات حالية.</div>`;
  const recent=[...state.cash].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,8);
  document.getElementById('recentCash').innerHTML=recent.length?recent.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(companyName(r.companyId))}</td><td>${esc(r.description)}</td><td>${esc(r.category)}</td><td>${fmt(r.income)}</td><td>${fmt(r.expense)}</td><td>${fmt(r.balance)}</td></tr>`).join(''):`<tr><td colspan="7" class="empty">لا توجد حركات خزينة.</td></tr>`;
}

function renderCompanies(c){
 c.innerHTML=`<div class="section-toolbar"><div><h3>الشركات</h3><div class="muted">الإعدادات المالية لكل شركة</div></div><button class="btn primary" data-action="add-company">+ شركة جديدة</button></div><div class="grid cards-4">${state.companies.map(co=>`<div class="panel"><div class="panel-head"><h3>${esc(co.name)}</h3><span class="pill ${co.active?'green':'gray'}">${co.active?'نشطة':'غير نشطة'}</span></div><div class="kpi-grid" style="grid-template-columns:1fr 1fr"><div class="kpi"><div class="label">الإيراد الشهري</div><div class="value">${fmt(co.monthlyRevenue)}</div></div><div class="kpi"><div class="label">الضريبة</div><div class="value">${num(co.taxRate)}%</div></div></div><div class="muted">الشركاء: ${co.partners?.length||0}</div><div class="btn-group" style="margin-top:12px"><button class="btn small ghost" data-action="edit-company" data-id="${co.id}">تعديل</button></div></div>`).join('')}</div>`;
}

function renderEmployees(c){
 const list=state.employees.filter(e=>currentCompany==='all'||e.companyId===currentCompany);
 c.innerHTML=`<div class="section-toolbar"><div><h3>الموظفون (${list.length})</h3><div class="muted">كل موظف له ID ثابت لمنع تكرار الأسماء</div></div><div class="toolbar-right"><input id="empSearch" class="select" placeholder="بحث بالاسم أو الرقم" /><button class="btn primary" data-action="add-employee">+ موظف</button></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>ID</th><th>الرقم الوظيفي</th><th>الاسم</th><th>الشركة</th><th>الوظيفة</th><th>قيمة اليوم</th><th>الحالة</th><th></th></tr></thead><tbody id="empRows">${list.map(e=>empRow(e)).join('')||`<tr><td colspan="8" class="empty">لا يوجد موظفون بعد.</td></tr>`}</tbody></table></div></div>`;
 document.getElementById('empSearch').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();document.getElementById('empRows').innerHTML=list.filter(x=>(x.name+x.job+x.employeeNo).toLowerCase().includes(q)).map(empRow).join('')||`<tr><td colspan="8" class="empty">لا توجد نتائج.</td></tr>`});
}
function empRow(e){return `<tr><td>${esc(e.id)}</td><td>${esc(e.employeeNo||'')}</td><td><b>${esc(e.name)}</b></td><td>${esc(companyName(e.companyId))}</td><td>${esc(e.job||'غفر')}</td><td>${fmt(e.dailyRate)}</td><td><span class="pill ${e.active?'green':'gray'}">${e.active?'نشط':'غير نشط'}</span></td><td><button class="btn small ghost" data-action="edit-employee" data-id="${e.id}">تعديل</button></td></tr>`}

function renderAttendance(c,selectedMonth){const cm=currentMonth();const monthKeyValue=selectedMonth||sel.att||monthKey(cm.y,cm.m);sel.att=monthKeyValue;const [y,m]=monthKeyValue.split('-').map(Number);const emps=empsForMonth(monthKeyValue,currentCompany);const dcount=daysInMonth(y,m);
 c.innerHTML=`<div class="section-toolbar"><div class="toolbar-left"><div class="field"><label>الشهر</label><input id="attMonth" type="month" value="${monthKeyValue}" /></div></div><div class="toolbar-right"><div class="muted">الحالة الافتراضية: اضغط على الخلية واختر الحالة</div></div></div><div class="panel"><div class="table-wrap"><table class="attendance-table"><thead><tr><th>الموظف</th>${Array.from({length:dcount},(_,i)=>`<th class="attendance-cell">${i+1}</th>`).join('')}<th>الأيام المستحقة</th></tr></thead><tbody>${emps.map(e=>{const row=state.attendance[monthKeyValue]?.[e.id]||{};const count=countPaid(row);return `<tr><td><b>${esc(e.name)}</b><div class="muted">${esc(companyName(e.companyId))}</div></td>${Array.from({length:dcount},(_,i)=>{const val=row[i+1]||'';return `<td class="attendance-cell"><select class="attendance-select" data-action="set-attendance" data-emp="${e.id}" data-day="${i+1}" data-month="${monthKeyValue}" ${(((state.payroll[monthKeyValue]||{}).items||{})[e.id]||{}).paid?'disabled':''}><option value="">—</option>${['حاضر','غياب','إجازة','مرضية','عطلة'].map(v=>`<option ${val===v?'selected':''}>${v}</option>`).join('')}</select></td>`}).join('')}<td><span class="pill blue">${count}</span></td></tr>`}).join('')||`<tr><td colspan="${dcount+2}" class="empty">أضف موظفين أولًا.</td></tr>`}</tbody></table></div></div>`;
 document.getElementById('attMonth').addEventListener('change',e=>renderAttendance(c,e.target.value));
}
function countPaid(row){return Object.values(row).filter(v=>state.settings.attendancePaid[v]).length}

function renderPayroll(c,selectedMonth){const cm=currentMonth();const mk=selectedMonth||sel.pay||monthKey(cm.y,cm.m);sel.pay=mk;const emps=empsForMonth(mk,currentCompany);const rows=emps.map(e=>calcPayroll(e,mk));const totals=rows.reduce((a,r)=>{a.gross+=r.gross;a.net+=r.net;a.loans+=r.loan;return a},{gross:0,net:0,loans:0});
 c.innerHTML=`<div class="section-toolbar"><div class="toolbar-left"><div class="field"><label>الشهر</label><input id="payMonth" type="month" value="${mk}" /></div></div><div class="toolbar-right"><button class="btn success" data-action="save-payroll" data-month="${mk}">اعتماد الشهر</button><button class="btn ghost" data-action="export-payroll" data-month="${mk}">Excel CSV</button></div></div><div class="kpi-grid"><div class="kpi"><div class="label">عدد الموظفين</div><div class="value">${rows.length}</div></div><div class="kpi"><div class="label">الإجمالي</div><div class="value">${fmt(totals.gross)}</div></div><div class="kpi"><div class="label">السلف</div><div class="value">${fmt(totals.loans)}</div></div><div class="kpi"><div class="label">الصافي</div><div class="value">${fmt(totals.net)}</div></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الشركة</th><th>قيمة اليوم</th><th>الأيام</th><th>الأساسي</th><th>بدلات</th><th>حوافز</th><th>الإجمالي</th><th>السلف</th><th>الخصومات</th><th>الصافي</th><th>الصرف</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.employee.name)}</b></td><td>${esc(companyName(r.employee.companyId))}</td><td>${fmt(r.daily)}</td><td>${r.days}</td><td>${fmt(r.basic)}</td><td><input class="inline-input" data-pay-field="allowance" data-emp="${r.employee.id}" data-month="${mk}" value="${r.allowance}" ${r.paid?'disabled':''}/></td><td><input class="inline-input" data-pay-field="bonus" data-emp="${r.employee.id}" data-month="${mk}" value="${r.bonus}" ${r.paid?'disabled':''}/></td><td>${fmt(r.gross)}</td><td>${fmt(r.loan)}</td><td><input class="inline-input" data-pay-field="deduction" data-emp="${r.employee.id}" data-month="${mk}" value="${r.deduction}" ${r.paid?'disabled':''}/></td><td><b>${fmt(r.net)}</b>${r.carry>0?`<div class="muted">يُرحَّل ${fmt(r.carry)}</div>`:''}</td><td><button class="btn small ${r.paid?'success':'ghost'}" data-action="payroll-paid" data-emp="${r.employee.id}" data-month="${mk}">${r.paid?'تم الصرف':'صرف'}</button></td></tr>`).join('')||`<tr><td colspan="12" class="empty">لا يوجد موظفون.</td></tr>`}</tbody></table></div></div>`;
 const pm=document.getElementById('payMonth');pm.addEventListener('change',()=>renderPayroll(c,pm.value));
 c.querySelectorAll('.inline-input').forEach(inp=>inp.addEventListener('change',()=>{if(!Auth.can('write')){showToast('صلاحيتك للعرض فقط');renderPayroll(c);return}const mk=inp.dataset.month,eid=inp.dataset.emp;state.payroll[mk]??={items:{}};state.payroll[mk].items??={};state.payroll[mk].items[eid]??={};state.payroll[mk].items[eid][inp.dataset.payField]=num(inp.value);saveState();renderPayroll(c)}));
}
function calcPayroll(e,mk){const old=((state.payroll[mk]||{}).items||{})[e.id]||{};if(old.paid&&old.snapshot)return {employee:e,...old.snapshot,paid:true};const row=(state.attendance[mk]||{})[e.id]||{};const days=countPaid(row);const daily=num(e.dailyRate);const basic=days*daily;const loan=state.loans.filter(l=>l.employeeId===e.id&&l.month===mk).reduce((s,l)=>s+Math.max(0,num(l.amount)-num(l.repaid)),0);const allowance=num(old.allowance),bonus=num(old.bonus),deduction=num(old.deduction);const gross=basic+allowance+bonus;const avail=Math.max(0,gross-deduction);const net=Math.max(0,avail-loan);const carry=Math.max(0,loan-avail);return {employee:e,days,daily,basic,allowance,bonus,gross,loan,deduction,net,carry,paid:Boolean(old.paid)}}

function renderLoans(c){const list=state.loans.filter(l=>currentCompany==='all'||l.companyId===currentCompany);c.innerHTML=`<div class="section-toolbar"><div><h3>السلف</h3><div class="muted">السلف مرتبطة بالموظف وتظهر تلقائيًا في المرتبات</div></div><button class="btn primary" data-action="add-loan">+ سلفة</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>الموظف</th><th>الشركة</th><th>المبلغ</th><th>المسدد</th><th>المتبقي</th><th>الشهر</th></tr></thead><tbody>${list.map(l=>`<tr><td>${esc(l.date)}</td><td>${esc(state.employees.find(e=>e.id===l.employeeId)?.name||'محذوف')}</td><td>${esc(companyName(l.companyId))}</td><td>${fmt(l.amount)}</td><td>${fmt(l.repaid)}</td><td><b>${fmt(Math.max(0,num(l.amount)-num(l.repaid)))}</b></td><td>${esc(l.month||'—')}</td></tr>`).join('')||`<tr><td colspan="7" class="empty">لا توجد سلف.</td></tr>`}</tbody></table></div></div><div class="panel section-gap"><div class="panel-head"><h3>التحويلات بين مايفين وايوان</h3><button class="btn small primary" data-action="add-transfer">+ تحويل</button></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>من</th><th>إلى</th><th>المبلغ</th><th>البيان</th></tr></thead><tbody>${state.transfers.map(t=>`<tr><td>${esc(t.date)}</td><td>${esc(companyName(t.fromCompanyId))}</td><td>${esc(companyName(t.toCompanyId))}</td><td>${fmt(t.amount)}</td><td>${esc(t.description)}</td></tr>`).join('')||`<tr><td colspan="5" class="empty">لا توجد تحويلات.</td></tr>`}</tbody></table></div></div>`}

function calcCash(companyId){let balance=0;state.cash.filter(x=>x.companyId===companyId).sort((a,b)=>new Date(a.date)-new Date(b.date)||String(a.id).localeCompare(String(b.id))).forEach(x=>{balance+=num(x.income)-num(x.expense)});return balance}
function deleteCash(id){const x=state.cash.find(c=>c.id===id);if(!x)return;const ref=x.ref||'';
 if(/^PAY-/.test(ref)){alert('هذه حركة صرف مرتب. ألغِ الصرف من شاشة المرتبات.');return}
 if(/^LOAN-/.test(ref)){const l=state.loans.find(v=>v.id===ref);if(l&&num(l.repaid)>0){alert('لا يمكن حذف سلفة خُصم جزء منها من مرتب. ألغِ صرف المرتب أولًا.');return}}
 if(!confirm('حذف هذه الحركة وكل ما يرتبط بها؟'))return;
 const affected=new Set([x.companyId]);
 if(/^LOAN-/.test(ref))state.loans=state.loans.filter(v=>v.id!==ref);
 else if(/^REV-/.test(ref))state.revenues=state.revenues.filter(v=>v.id!==ref);
 else if(/^EXP-/.test(ref))state.expenses=state.expenses.filter(v=>v.id!==ref);
 else if(/^PP-/.test(ref))state.partnerPayments=state.partnerPayments.filter(v=>v.id!==ref);
 else if(/^TR-/.test(ref)){state.cash.filter(c=>c.ref===ref).forEach(c=>affected.add(c.companyId));state.transfers=state.transfers.filter(v=>v.id!==ref);state.cash=state.cash.filter(c=>c.ref!==ref)}
 state.cash=state.cash.filter(c=>c.id!==id);
 affected.forEach(cid=>recalcCashBalances(cid));audit('حذف حركة خزينة',{id,ref,description:x.description});saveState();render()}
function recalcCashBalances(companyId){let balance=0;state.cash.filter(x=>x.companyId===companyId).sort((a,b)=>new Date(a.date)-new Date(b.date)||String(a.id).localeCompare(String(b.id))).forEach(x=>{balance+=num(x.income)-num(x.expense);x.balance=balance});}
const arNorm=v=>String(v??'').toLowerCase().replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).trim();
function cashFilters(){if(!sel.cq)sel.cq={q:'',type:'all',cat:'all',from:'',to:''};return sel.cq}
function cashFiltered(){const f=cashFilters();const words=arNorm(f.q).split(/\s+/).filter(Boolean);
 return state.cash.filter(x=>currentCompany==='all'||x.companyId===currentCompany).filter(x=>{
  if(f.type==='in'&&!(num(x.income)>0))return false;if(f.type==='out'&&!(num(x.expense)>0))return false;
  if(f.cat!=='all'&&(x.category||'')!==f.cat)return false;if(f.from&&x.date<f.from)return false;if(f.to&&x.date>f.to)return false;
  if(!words.length)return true;
  const hay=arNorm([x.date,companyName(x.companyId),x.description,x.category,x.holder,x.note,x.income,x.expense,fmt(x.income),fmt(x.expense),x.balance].join(' '));
  return words.every(w=>hay.includes(w))}).sort((a,b)=>new Date(b.date)-new Date(a.date))}
const cashActive=()=>{const f=cashFilters();return Boolean(f.q.trim()||f.type!=='all'||f.cat!=='all'||f.from||f.to)};
function cashKpisHtml(list){const total=state.cash.filter(x=>currentCompany==='all'||x.companyId===currentCompany).length;return `<div class="kpi"><div class="label">إيرادات العرض</div><div class="value">${fmt(list.reduce((t,x)=>t+num(x.income),0))}</div></div><div class="kpi"><div class="label">منصرف العرض</div><div class="value">${fmt(list.reduce((t,x)=>t+num(x.expense),0))}</div></div><div class="kpi"><div class="label">عدد الحركات</div><div class="value">${list.length}${cashActive()?` <small>من ${total}</small>`:''}</div></div>`}
function cashRowsHtml(list){return list.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(companyName(x.companyId))}</td><td>${esc(x.description)}</td><td>${esc(x.category)}</td><td>${fmt(x.income)}</td><td>${fmt(x.expense)}</td><td><b>${fmt(x.balance)}</b></td><td>${esc(x.holder||'')}</td><td>${esc(x.note||'')}</td><td><button class="btn small danger" data-action="delete-cash" data-id="${x.id}">حذف</button></td></tr>`).join('')||`<tr><td colspan="10" class="empty">${cashActive()?'لا توجد نتائج مطابقة للبحث.':'لا توجد حركات خزينة.'}</td></tr>`}
function renderCash(c){const f=cashFilters();const base=state.cash.filter(x=>currentCompany==='all'||x.companyId===currentCompany);const cats=[...new Set(base.map(x=>x.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ar'));if(f.cat!=='all'&&!cats.includes(f.cat))f.cat='all';
 c.innerHTML=`<div class="section-toolbar"><div class="btn-group" id="cashKpis">${cashKpisHtml(cashFiltered())}</div><div class="btn-group"><button class="btn success" data-action="add-revenue">+ إيراد</button><button class="btn secondary" data-action="add-expense">+ مصروف</button><button class="btn primary" data-action="add-cash">+ حركة أخرى</button></div></div><div class="panel section-gap"><div class="search-bar"><input id="cashQ" type="search" placeholder="🔍 ابحث: بيان، بند، بيد من، ملاحظة، مبلغ، تاريخ…" value="${esc(f.q)}" autocomplete="off" /><select id="cashType"><option value="all">الكل</option><option value="in" ${f.type==='in'?'selected':''}>إيرادات فقط</option><option value="out" ${f.type==='out'?'selected':''}>منصرفات فقط</option></select><select id="cashCat"><option value="all">كل البنود</option>${cats.map(k=>`<option value="${esc(k)}" ${f.cat===k?'selected':''}>${esc(k)}</option>`).join('')}</select><label class="search-date">من <input id="cashFrom" type="date" value="${esc(f.from)}" /></label><label class="search-date">إلى <input id="cashTo" type="date" value="${esc(f.to)}" /></label><button class="btn ghost small" id="cashClear">مسح البحث</button><button class="btn ghost small" id="cashExport">تصدير النتائج CSV</button></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>الشركة</th><th>البيان</th><th>البند</th><th>الإيراد</th><th>المنصرف</th><th>الرصيد</th><th>بيد من</th><th>ملاحظات</th><th></th></tr></thead><tbody id="cashBody">${cashRowsHtml(cashFiltered())}</tbody></table></div></div>`;
 const g=id=>document.getElementById(id);const upd=()=>{const l=cashFiltered();g('cashKpis').innerHTML=cashKpisHtml(l);g('cashBody').innerHTML=cashRowsHtml(l)};
 g('cashQ').addEventListener('input',e=>{f.q=e.target.value;upd()});
 g('cashType').addEventListener('change',e=>{f.type=e.target.value;upd()});g('cashCat').addEventListener('change',e=>{f.cat=e.target.value;upd()});
 g('cashFrom').addEventListener('change',e=>{f.from=e.target.value;upd()});g('cashTo').addEventListener('change',e=>{f.to=e.target.value;upd()});
 g('cashClear').addEventListener('click',()=>{sel.cq={q:'',type:'all',cat:'all',from:'',to:''};renderCash(c);g('cashQ').focus()});
 g('cashExport').addEventListener('click',()=>{const l=cashFiltered();download(`نتائج_الخزينة_${today()}.csv`,['التاريخ,الشركة,البيان,البند,الإيراد,المنصرف,الرصيد,بيد من,ملاحظات',...l.map(x=>[x.date,companyName(x.companyId),x.description,x.category,x.income,x.expense,x.balance,x.holder,x.note].map(csvCell).join(','))].join('\n'),'text/csv;charset=utf-8')})}

function partnerDue(co,p,st,mk){const share=Math.max(0,st.profit)*num(p.rate)/100;const adj=state.partnerAdjustments.filter(x=>x.companyId===co.id&&x.partnerId===p.id&&x.month===mk).reduce((t,x)=>t+num(x.amount),0);const paid=state.partnerPayments.filter(x=>x.companyId===co.id&&x.partnerId===p.id&&x.month===mk).reduce((t,x)=>t+num(x.amount),0);return {share,adj,due:share+adj,paid,rest:share+adj-paid}}
function renderSettlements(c,selectedMonth){const cm=currentMonth();const sm0=selectedMonth||sel.settle;if(sm0){const [sy,sm]=sm0.split('-').map(Number);cm.y=sy;cm.m=sm}const mk=monthKey(cm.y,cm.m);sel.settle=mk;const companies=state.companies.filter(co=>currentCompany==='all'||co.id===currentCompany);
 c.innerHTML=`<div class="section-toolbar"><div><h3>التسويات الشهرية</h3><div class="muted">الضريبة + التكلفة + الربح + نصيب الشركاء</div></div><div class="field"><label>الشهر</label><input id="settleMonth" type="month" value="${mk}" /></div></div>${companies.map(co=>{const st=calcSummary(co.id,cm);const adjs=state.partnerAdjustments.filter(x=>x.companyId===co.id&&x.month===mk);return `<div class="panel section-gap"><div class="panel-head"><div><h3>${esc(co.name)}</h3><div class="muted">إيراد شهري إعداداته ${fmt(co.monthlyRevenue)}</div></div><span><span class="pill blue">${num(co.taxRate)}% ضريبة</span> ${st.estimated?'<span class="pill gray">إيراد تقديري من الإعدادات</span>':''}</span></div><div class="kpi-grid"><div class="kpi"><div class="label">الإيراد الشامل</div><div class="value">${fmt(st.revenue)}</div></div><div class="kpi"><div class="label">الضريبة</div><div class="value">${fmt(st.tax)}</div></div><div class="kpi"><div class="label">التكلفة</div><div class="value">${fmt(st.cost)}</div></div><div class="kpi"><div class="label">صافي الربح</div><div class="value">${fmt(st.profit)}</div></div></div><div class="table-wrap"><table><thead><tr><th>الشريك</th><th>النسبة</th><th>نصيب النسبة</th><th>مبلغ إضافي/خصم</th><th>المستحق</th><th>المدفوع</th><th>المتبقي</th></tr></thead><tbody>${(co.partners||[]).map(p=>{const d=partnerDue(co,p,st,mk);return `<tr><td>${esc(p.name)}</td><td>${num(p.rate)}%</td><td>${fmt(d.share)}</td><td>${fmt(d.adj)}</td><td>${fmt(d.due)}</td><td>${fmt(d.paid)}</td><td><b>${fmt(d.rest)}</b></td></tr>`}).join('')||`<tr><td colspan="7" class="empty">أضف الشركاء من إعدادات الشركة.</td></tr>`}</tbody></table></div>${adjs.length?`<div class="muted" style="margin-top:10px">المبالغ الإضافية لهذا الشهر:</div>${adjs.map(x=>{const p=(co.partners||[]).find(q=>q.id===x.partnerId);return `<div class="adj-row"><span>${esc(p?p.name:'—')}: <b>${fmt(x.amount)}</b> ${x.note?'— '+esc(x.note):''}</span><button class="btn small danger" data-action="delete-partner-adjustment" data-id="${x.id}">حذف</button></div>`}).join('')}`:''}<div class="btn-group" style="margin-top:12px"><button class="btn success" data-action="add-partner-payment" data-company="${co.id}">تسجيل دفع شريك</button><button class="btn ghost" data-action="add-partner-adjustment" data-company="${co.id}">إضافة مبلغ لشريك</button></div></div>`}).join('')}`;
 const sm=document.getElementById('settleMonth');sm?.addEventListener('change',()=>renderSettlements(c,sm.value));
}
function addPartnerAdjustment(companyId){const co=state.companies.find(x=>x.id===companyId);if(!(co.partners||[]).length)return alert('أضف الشركاء أولًا من إعدادات الشركة');const mk=sel.settle||monthKey(currentMonth().y,currentMonth().m);
 openModal(`مبلغ لشريك — ${esc(co.name)}`,`<div class="field-grid"><div class="field"><label>الشريك</label><select id="fPartner">${co.partners.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>النوع</label><select id="fType"><option value="1">إضافة للمستحق</option><option value="-1">خصم من المستحق</option></select></div><div class="field"><label>المبلغ</label><input id="fAmount" type="number" /></div><div class="field"><label>الشهر</label><input id="fMonth" type="month" value="${mk}" /></div><div class="field full"><label>ملاحظة</label><textarea id="fNote"></textarea></div></div>`,w=>{const amt=num(w.querySelector('#fAmount').value);if(amt<=0||!w.querySelector('#fMonth').value)return false;const x={id:uid('PA'),companyId,partnerId:w.querySelector('#fPartner').value,month:w.querySelector('#fMonth').value,amount:amt*Number(w.querySelector('#fType').value),note:w.querySelector('#fNote').value.trim(),date:today()};state.partnerAdjustments.push(x);audit('مبلغ إضافي لشريك',{companyId,partnerId:x.partnerId,month:x.month,amount:x.amount});saveState();render();return true})}
function deletePartnerAdjustment(id){if(!confirm('حذف هذا المبلغ؟'))return;state.partnerAdjustments=state.partnerAdjustments.filter(x=>x.id!==id);audit('حذف مبلغ شريك',{id});saveState();render()}

function calcSummary(companyId,cm){const mk=monthKey(cm.y,cm.m);const co=state.companies.find(x=>x.id===companyId);const actual=state.revenues.filter(r=>r.companyId===companyId&&r.month===mk).reduce((t,r)=>t+num(r.amount),0);const estimated=actual<=0;const revenue=estimated?num(co.monthlyRevenue):actual;let tax=0;if(co.taxBasis==='gross')tax=revenue*num(co.taxRate)/100;else if(co.taxBasis==='net')tax=revenue-(revenue/(1+num(co.taxRate)/100));const payroll=empsForMonth(mk,companyId).reduce((t,e)=>t+calcPayroll(e,mk).gross,0);const expenses=state.expenses.filter(x=>x.companyId===companyId&&x.month===mk).reduce((t,x)=>t+num(x.amount),0);const cost=payroll+expenses;return {revenue,estimated,tax,netRevenue:revenue-tax,payroll,expenses,cost,profit:revenue-tax-cost}}

function slipEmpOptions(){const g=id=>document.getElementById(id);const mk=g('repSlipMonth').value,co=g('repSlipCompany').value;const list=mk?empsForMonth(mk,co):[];g('repSlipEmp').innerHTML='<option value="all">كل الموظفين (صفحة لكل موظف)</option>'+list.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}
function reportPayslip(mode){const g=id=>document.getElementById(id);const mk=g('repSlipMonth').value,co=g('repSlipCompany').value,eid=g('repSlipEmp').value;if(!mk)return alert('اختر الشهر');let emps=empsForMonth(mk,co);if(eid!=='all')emps=emps.filter(e=>e.id===eid);if(!emps.length)return alert('لا يوجد موظفون لهذا الاختيار');
 const slips=emps.map(e=>{const p=calcPayroll(e,mk);const row=(state.attendance[mk]||{})[e.id]||{};const cnt={};Object.values(row).forEach(v=>{cnt[v]=(cnt[v]||0)+1});const deducted=p.loan-p.carry;
  const att=Object.entries(cnt).map(([k,v])=>`${esc(k)}: ${v}`).join(' — ')||'لا يوجد تسجيل';
  return `<div class="slip">${logoHead()}<h2>مفردات مرتب شهر ${esc(mk)}</h2><table class="info"><tr><th>الاسم</th><td>${esc(e.name)}</td><th>الرقم الوظيفي</th><td>${esc(e.employeeNo||'')}</td></tr><tr><th>الشركة</th><td>${esc(companyName(e.companyId))}</td><th>الوظيفة</th><td>${esc(e.job||'')}</td></tr></table><table><thead><tr><th>البند</th><th>القيمة</th></tr></thead><tbody><tr><td>الأيام المستحقة</td><td>${p.days}</td></tr><tr><td>قيمة اليوم</td><td>${rn(p.daily)}</td></tr><tr><td>الأساسي</td><td>${rn(p.basic)}</td></tr><tr><td>بدلات</td><td>${rn(p.allowance)}</td></tr><tr><td>حوافز</td><td>${rn(p.bonus)}</td></tr><tr><td><b>الإجمالي</b></td><td><b>${rn(p.gross)}</b></td></tr><tr><td>خصومات</td><td>${rn(p.deduction)}</td></tr><tr><td>سلف مخصومة</td><td>${rn(deducted)}</td></tr><tr><td><b>الصافي المستحق</b></td><td><b>${rn(p.net)}</b></td></tr>${p.carry>0?`<tr><td>سلف مرحّلة للشهر التالي</td><td>${rn(p.carry)}</td></tr>`:''}</tbody></table><p>الحضور: ${att}</p><p>حالة الصرف: ${p.paid?'تم الصرف':'لم يُصرف بعد'}</p><div class="sign"><span>توقيع المستلم: ____________</span><span>المحاسب: ____________</span></div></div>`}).join('');
 const html=`<html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>مفردات مرتب ${esc(mk)}</title><style>@page{size:A4 portrait;margin:14mm}body{font-family:Arial,Tahoma,sans-serif}h1{margin:0;color:#b8860b}h2{margin:4px 0 12px}table{border-collapse:collapse;width:100%;margin:8px 0}th,td{border:1px solid #999;padding:6px;text-align:right}thead th{background:#111;color:#fff}.info th{background:#f3f3f3;color:#000;width:18%}.slip{page-break-after:always;padding:6px}.slip:last-child{page-break-after:auto}.sign{display:flex;justify-content:space-between;margin-top:36px}</style></head><body>${slips}</body></html>`;
 if(mode==='print')return printHtml(html);return download(`مفردات_مرتب_${mk}.doc`,html,'application/msword')}
function renderReports(c){const cmk=monthKey(currentMonth().y,currentMonth().m);const compOpts=(all)=>`${all?'<option value="all">كل الشركات</option>':''}${state.companies.map(co=>`<option value="${co.id}">${esc(co.name)}</option>`).join('')}`;
 c.innerHTML=`<div class="grid two-col"><div class="panel"><div class="panel-head"><h3>تقرير المرتبات الشهري</h3></div><div class="field-grid"><div class="field"><label>الشهر</label><input id="repMonth" type="month" value="${cmk}" /></div><div class="field"><label>الشركة</label><select id="repCompany">${compOpts(true)}</select></div></div><div class="btn-group" style="margin-top:12px"><button class="btn primary" data-action="report-payroll-print">طباعة / PDF</button><button class="btn ghost" data-action="report-payroll-csv">Excel CSV</button><button class="btn ghost" data-action="report-payroll-word">Word</button></div></div>
 <div class="panel"><div class="panel-head"><h3>مفردات المرتب (لكل موظف)</h3></div><div class="field-grid"><div class="field"><label>الشهر</label><input id="repSlipMonth" type="month" value="${cmk}" /></div><div class="field"><label>الشركة</label><select id="repSlipCompany">${compOpts(true)}</select></div><div class="field full"><label>الموظف</label><select id="repSlipEmp"></select></div></div><div class="btn-group" style="margin-top:12px"><button class="btn primary" data-action="report-slip-print">طباعة / PDF</button><button class="btn ghost" data-action="report-slip-word">Word</button></div></div></div>
 <div class="grid two-col section-gap"><div class="panel"><div class="panel-head"><h3>تقرير خزينة شركة</h3><span class="muted">لكل شركة على حدة</span></div><div class="field-grid"><div class="field"><label>الشركة</label><select id="repCashCompany">${compOpts(false)}</select></div><div class="field"><label>من شهر (اختياري)</label><input id="repCashFrom" type="month" /></div><div class="field"><label>إلى شهر (اختياري)</label><input id="repCashTo" type="month" /></div></div><div class="btn-group" style="margin-top:12px"><button class="btn primary" data-action="report-cash-print">طباعة / PDF</button><button class="btn ghost" data-action="report-cash-csv">Excel CSV</button><button class="btn ghost" data-action="report-cash-word">Word</button></div></div>
 <div class="panel"><div class="panel-head"><h3>تقرير التسوية</h3></div><div class="field"><label>الشهر</label><input id="repSettleMonth" type="month" value="${cmk}" /></div><div class="btn-group" style="margin-top:12px"><button class="btn primary" data-action="report-settle-print">طباعة / PDF</button><button class="btn ghost" data-action="report-settle-csv">Excel CSV</button><button class="btn ghost" data-action="report-settle-word">Word</button></div></div></div>`;
 ['repSlipMonth','repSlipCompany'].forEach(id=>document.getElementById(id).addEventListener('change',slipEmpOptions));
 if(currentCompany!=='all')document.getElementById('repCashCompany').value=currentCompany;slipEmpOptions()}

function renderSettings(c){c.innerHTML=`<div class="grid two-col"><div class="panel"><div class="panel-head"><h3>إعدادات الحضور</h3></div><div class="muted" style="margin-bottom:12px">حدد الحالات التي تُحسب كيوم مستحق.</div>${Object.entries(state.settings.attendancePaid).map(([k,v])=>`<div class="company-row"><span>${esc(k)}</span><button class="btn small ${v?'success':'ghost'}" data-action="toggle-paid" data-status="${k}">${v?'مدفوع':'غير مدفوع'}</button></div>`).join('')}</div><div class="panel"><div class="panel-head"><h3>النسخ الاحتياطي</h3></div><div class="muted">كل البيانات في هذا الجهاز تعتمد على المتصفح، لذا النسخة الاحتياطية ضرورية.</div><div class="btn-group" style="margin-top:14px"><button class="btn primary" data-action="backup">تنزيل نسخة كاملة</button><label class="btn ghost" for="restoreFile">استرجاع نسخة</label><input id="restoreFile" type="file" accept="application/json" hidden /></div><div class="muted" style="margin-top:12px">آخر نسخة: ${state.settings.lastBackupAt?new Date(state.settings.lastBackupAt).toLocaleString('ar-EG'):'لا توجد'}</div></div></div><div class="panel section-gap"><div class="panel-head"><h3>سجل العمليات</h3></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>المستخدم</th><th>العملية</th><th>التفاصيل</th></tr></thead><tbody>${state.audit.slice(-30).reverse().map(a=>`<tr><td>${new Date(a.at).toLocaleString('ar-EG')}</td><td>${esc(a.by||'')}</td><td>${esc(a.action)}</td><td>${esc(JSON.stringify(a.meta))}</td></tr>`).join('')||`<tr><td colspan="4" class="empty">لا توجد عمليات.</td></tr>`}</tbody></table></div></div>`;document.getElementById('restoreFile').addEventListener('change',restore)}

function renderBackupBadge(){const el=document.getElementById('backupBadge');if(!el)return;if(!state.settings.lastBackupAt){el.textContent='⚠ لم يتم إنشاء نسخة بعد';return}const days=Math.floor((Date.now()-new Date(state.settings.lastBackupAt).getTime())/86400000);el.textContent=days>7?`⚠ آخر نسخة منذ ${days} يومًا`:`✓ آخر نسخة منذ ${days} يوم`}

function openModal(title,body,onSave,opts={}){if(!opts.force&&!Auth.can('write')){showToast('صلاحيتك للعرض فقط');return}const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal"><div class="modal-head"><h3>${title}</h3><button class="close-btn">✕</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="btn primary" id="modalSave">حفظ</button><button class="btn ghost" id="modalCancel">إلغاء</button></div></div>`;document.body.appendChild(wrap);const close=()=>wrap.remove();wrap.querySelector('.close-btn').onclick=close;wrap.querySelector('#modalCancel').onclick=close;wrap.querySelector('#modalSave').onclick=()=>{const r=onSave(wrap);if(r)close();else if(r===false)showToast('راجع البيانات المطلوبة')}}

function handleClick(e){const b=e.target.closest('[data-action]');if(!b){const rt=e.target.closest('[data-route]');if(rt){currentRoute=rt.dataset.route;render();}return;}const a=b.dataset.action;const id=b.dataset.id;if(!Auth.can('write')&&!/^(report-|export-)/.test(a)){showToast('صلاحيتك للعرض فقط');return}if(a==='add-user')return addUserModal();if(a==='edit-user')return editUserModal(id);if(a==='delete-user')return deleteUserAction(id);if(a==='add-partner-adjustment')return addPartnerAdjustment(b.dataset.company);if(a==='delete-partner-adjustment')return deletePartnerAdjustment(id);if(a==='report-slip-print')return reportPayslip('print');if(a==='report-slip-word')return reportPayslip('word');if(a==='export-payroll')return payrollOut('csv',b.dataset.month,currentCompany);if(a==='delete-cash')return deleteCash(id);if(a==='report-cash-word')return reportCash('word');
 if(a==='add-company')return addCompany();if(a==='add-revenue')return addRevenue();if(a==='add-expense')return addExpense();if(a==='edit-company')return editCompany(id);if(a==='add-employee')return addEmployee();if(a==='edit-employee')return editEmployee(id);if(a==='add-loan')return addLoan();if(a==='add-cash')return addCash();if(a==='add-transfer')return addTransfer();if(a==='save-payroll')return savePayroll(b.dataset.month);if(a==='payroll-paid')return togglePayrollPaid(b.dataset.emp,b.dataset.month);if(a==='toggle-paid'){state.settings.attendancePaid[b.dataset.status]=!state.settings.attendancePaid[b.dataset.status];audit('تعديل احتساب الحضور',{status:b.dataset.status});saveState();render();}if(a==='add-partner-payment')return addPartnerPayment(b.dataset.company);if(a==='backup')return backup();if(a==='report-payroll-print')return reportPayroll('print');if(a==='report-payroll-csv')return reportPayroll('csv');if(a==='report-payroll-word')return reportPayroll('word');if(a==='report-settle-print')return reportSettlement('print');if(a==='report-settle-csv')return reportSettlement('csv');if(a==='report-settle-word')return reportSettlement('word');if(a==='report-cash-print')return reportCash('print');if(a==='report-cash-csv')return reportCash('csv');
}

document.addEventListener('change',e=>{if(e.target.matches('[data-action="set-attendance"]')){if(!Auth.can('write')){showToast('صلاحيتك للعرض فقط');render();return}const mk=e.target.dataset.month,eid=e.target.dataset.emp,day=e.target.dataset.day;state.attendance[mk]??={};state.attendance[mk][eid]??={};if(e.target.value)state.attendance[mk][eid][day]=e.target.value;else delete state.attendance[mk][eid][day];saveState();const pill=e.target.closest('tr')?.querySelector('.pill');if(pill)pill.textContent=countPaid(state.attendance[mk][eid]);showToast('تم حفظ الحضور')}})

function addCompany(){openModal('إضافة شركة',`<div class="field-grid"><div class="field"><label>اسم الشركة</label><input id="fName" /></div><div class="field"><label>الإيراد الشهري</label><input id="fRevenue" type="number" /></div><div class="field"><label>الضريبة %</label><input id="fTax" type="number" step="0.01" /></div><div class="field"><label>أساس الضريبة</label><select id="fBasis"><option value="gross">نسبة تُحسب من الإيراد</option><option value="net">الإيراد شامل الضريبة (تُستخرج منه)</option></select></div></div>`,w=>{const name=w.querySelector('#fName').value.trim();if(!name)return false;state.companies.push({id:uid('CO'),name,monthlyRevenue:num(w.querySelector('#fRevenue').value),taxRate:num(w.querySelector('#fTax').value),taxBasis:w.querySelector('#fBasis').value,active:true,partners:[]});audit('إضافة شركة',{name});saveState();refreshCompanyFilter();render();return true})}
function editCompany(id){const co=state.companies.find(x=>x.id===id);openModal('تعديل الشركة',`<div class="field-grid"><div class="field"><label>اسم الشركة</label><input id="fName" value="${esc(co.name)}" /></div><div class="field"><label>الإيراد الشهري</label><input id="fRevenue" type="number" value="${co.monthlyRevenue}" /></div><div class="field"><label>الضريبة %</label><input id="fTax" type="number" step="0.01" value="${co.taxRate}" /></div><div class="field"><label>أساس الضريبة</label><select id="fBasis"><option value="gross" ${co.taxBasis==='gross'?'selected':''}>نسبة تُحسب من الإيراد</option><option value="net" ${co.taxBasis==='net'?'selected':''}>الإيراد شامل الضريبة (تُستخرج منه)</option></select></div></div><div style="margin-top:16px"><div class="panel-head"><h3>الشركاء</h3><button class="btn small primary" type="button" id="addPartner">+ شريك</button></div><div id="partnersBox">${(co.partners||[]).map((p,i)=>`<div class="company-row partner-edit" data-pid="${p.id}"><div><input class="p-name select" value="${esc(p.name)}"/><input class="p-rate select" type="number" value="${p.rate}" style="width:100px"/> %</div><button class="btn small danger remove-partner">حذف</button></div>`).join('')}</div></div>`,w=>{const _sum=[...w.querySelectorAll('.partner-edit')].reduce((t,el)=>t+num(el.querySelector('.p-rate').value),0);if(_sum>100){alert('مجموع نسب الشركاء يتجاوز 100%');return false}co.name=w.querySelector('#fName').value.trim()||co.name;co.monthlyRevenue=num(w.querySelector('#fRevenue').value);co.taxRate=num(w.querySelector('#fTax').value);co.taxBasis=w.querySelector('#fBasis').value;co.partners=[...w.querySelectorAll('.partner-edit')].map(el=>({id:el.dataset.pid||uid('PAR'),name:el.querySelector('.p-name').value.trim(),rate:num(el.querySelector('.p-rate').value)})).filter(p=>p.name);audit('تعديل شركة',{companyId:id});saveState();render();return true});
 setTimeout(()=>{const wrap=document.querySelector('.modal-backdrop');wrap?.querySelector('#addPartner')?.addEventListener('click',()=>{const box=wrap.querySelector('#partnersBox');const id=uid('PAR');box.insertAdjacentHTML('beforeend',`<div class="company-row partner-edit" data-pid="${id}"><div><input class="p-name select" placeholder="اسم الشريك"/><input class="p-rate select" type="number" placeholder="%" style="width:100px"/> %</div><button class="btn small danger remove-partner">حذف</button></div>`)}) ;wrap?.querySelector('#partnersBox')?.addEventListener('click',e=>{if(e.target.closest('.remove-partner'))e.target.closest('.partner-edit').remove()})},0)}
function addEmployee(){openModal('إضافة موظف',`<div class="field-grid"><div class="field"><label>الرقم الوظيفي</label><input id="fNo" /></div><div class="field"><label>الاسم</label><input id="fName" /></div><div class="field"><label>الشركة</label><select id="fCompany">${state.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>الوظيفة</label><input id="fJob" value="غفر" /></div><div class="field"><label>قيمة اليوم</label><input id="fRate" type="number" value="200" /></div></div>`,w=>{const name=w.querySelector('#fName').value.trim();if(!name)return false;{const _d=dupEmployee(name,w.querySelector('#fNo').value.trim(),w.querySelector('#fCompany').value);if(_d){alert(_d);return false}}state.employees.push({id:uid('EMP'),employeeNo:w.querySelector('#fNo').value.trim(),name,companyId:w.querySelector('#fCompany').value,job:w.querySelector('#fJob').value.trim()||'غفر',dailyRate:num(w.querySelector('#fRate').value)||200,active:true});audit('إضافة موظف',{name});saveState();render();showToast('تمت إضافة الموظف');return true})}
function editEmployee(id){const e=state.employees.find(x=>x.id===id);openModal('تعديل الموظف',`<div class="field-grid"><div class="field"><label>الرقم الوظيفي</label><input id="fNo" value="${esc(e.employeeNo)}" /></div><div class="field"><label>الاسم</label><input id="fName" value="${esc(e.name)}" /></div><div class="field"><label>الشركة</label><select id="fCompany">${state.companies.map(c=>`<option value="${c.id}" ${e.companyId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>الوظيفة</label><input id="fJob" value="${esc(e.job)}" /></div><div class="field"><label>قيمة اليوم</label><input id="fRate" type="number" value="${e.dailyRate}" /></div><div class="field"><label>الحالة</label><select id="fActive"><option value="1" ${e.active?'selected':''}>نشط</option><option value="0" ${!e.active?'selected':''}>غير نشط</option></select></div></div>`,w=>{const _d=dupEmployee(w.querySelector('#fName').value.trim()||e.name,w.querySelector('#fNo').value.trim(),w.querySelector('#fCompany').value,id);if(_d){alert(_d);return false}e.employeeNo=w.querySelector('#fNo').value.trim();e.name=w.querySelector('#fName').value.trim()||e.name;e.companyId=w.querySelector('#fCompany').value;e.job=w.querySelector('#fJob').value.trim()||'غفر';e.dailyRate=num(w.querySelector('#fRate').value)||200;e.active=w.querySelector('#fActive').value==='1';audit('تعديل موظف',{employeeId:id});saveState();render();return true})}
function addLoan(){openModal('إضافة سلفة',`<div class="field-grid"><div class="field span-2"><label>الموظف</label><select id="fEmp">${state.employees.filter(e=>e.active).map(e=>`<option value="${e.id}">${esc(e.name)} — ${esc(companyName(e.companyId))}</option>`).join('')}</select></div><div class="field"><label>المبلغ</label><input id="fAmount" type="number" /></div><div class="field"><label>الشهر الذي تخصم منه</label><input id="fMonth" type="month" value="${monthKey(currentMonth().y,currentMonth().m)}" /></div><div class="field full"><label>ملاحظات</label><textarea id="fNote"></textarea></div></div>`,w=>{const eid=w.querySelector('#fEmp').value,e=state.employees.find(x=>x.id===eid);if(!e||num(w.querySelector('#fAmount').value)<=0)return false;const amount=num(w.querySelector('#fAmount').value);const loan={id:uid('LOAN'),employeeId:eid,companyId:e.companyId,date:today(),amount,repaid:0,month:w.querySelector('#fMonth').value,note:w.querySelector('#fNote').value};state.loans.push(loan);state.cash.push({id:uid('CASH'),companyId:e.companyId,date:loan.date,category:'سلف',income:0,expense:amount,balance:0,holder:'',description:`سلفة ${e.name}`,ref:loan.id,note:loan.note});recalcCashBalances(e.companyId);audit('إضافة سلفة',{employeeId:eid});saveState();render();return true})}
function addRevenue(){openModal('إضافة إيراد',`<div class="field-grid"><div class="field"><label>الشركة</label><select id="fCompany">${state.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>التاريخ</label><input id="fDate" type="date" value="${today()}" /></div><div class="field"><label>الشهر</label><input id="fMonth" type="month" value="${monthKey(currentMonth().y,currentMonth().m)}" /></div><div class="field"><label>المبلغ</label><input id="fAmount" type="number" /></div><div class="field span-2"><label>العميل / البيان</label><input id="fDesc" /></div><div class="field full"><label>ملاحظات</label><textarea id="fNote"></textarea></div></div>`,w=>{const cid=w.querySelector('#fCompany').value;const amount=num(w.querySelector('#fAmount').value);if(amount<=0||!w.querySelector('#fDate').value||!w.querySelector('#fMonth').value)return false;const r={id:uid('REV'),companyId:cid,date:w.querySelector('#fDate').value,month:w.querySelector('#fMonth').value,amount,description:w.querySelector('#fDesc').value,note:w.querySelector('#fNote').value};state.revenues.push(r);state.cash.push({id:uid('CASH'),companyId:cid,date:r.date,category:'إيرادات',income:amount,expense:0,balance:0,holder:'',description:r.description||'إيراد',ref:r.id,note:r.note});recalcCashBalances(cid);audit('إضافة إيراد',{companyId:cid,amount});saveState();render();return true})}
function addExpense(){openModal('إضافة مصروف',`<div class="field-grid"><div class="field"><label>الشركة</label><select id="fCompany">${state.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>التاريخ</label><input id="fDate" type="date" value="${today()}" /></div><div class="field"><label>الشهر</label><input id="fMonth" type="month" value="${monthKey(currentMonth().y,currentMonth().m)}" /></div><div class="field"><label>المبلغ</label><input id="fAmount" type="number" /></div><div class="field"><label>بند المصروف</label><input id="fDesc" /></div><div class="field"><label>بيد من</label><select id="fHolder"><option>مصطفى</option><option>سعد</option><option>خالد</option><option>الشيخ محمد</option><option>أحمد</option></select></div><div class="field full"><label>ملاحظات</label><textarea id="fNote"></textarea></div></div>`,w=>{const cid=w.querySelector('#fCompany').value;const amount=num(w.querySelector('#fAmount').value);if(amount<=0||!w.querySelector('#fDate').value||!w.querySelector('#fMonth').value)return false;const x={id:uid('EXP'),companyId:cid,date:w.querySelector('#fDate').value,month:w.querySelector('#fMonth').value,amount,description:w.querySelector('#fDesc').value,note:w.querySelector('#fNote').value,holder:w.querySelector('#fHolder').value};state.expenses.push(x);state.cash.push({id:uid('CASH'),companyId:cid,date:x.date,category:'مصاريف',income:0,expense:amount,balance:0,holder:x.holder,description:x.description||'مصروف',ref:x.id,note:x.note});recalcCashBalances(cid);audit('إضافة مصروف',{companyId:cid,amount});saveState();render();return true})}
function addCash(){openModal('إضافة حركة خزينة',`<div class="field-grid"><div class="field"><label>الشركة</label><select id="fCompany">${state.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>التاريخ</label><input id="fDate" type="date" value="${today()}" /></div><div class="field"><label>البند</label><select id="fCategory"><option>إيرادات</option><option>مرتبات</option><option>مصاريف</option><option>سلف</option><option>شركاء</option><option>ضرائب</option><option>أخرى</option></select></div><div class="field"><label>الإيراد</label><input id="fIncome" type="number" /></div><div class="field"><label>المنصرف</label><input id="fExpense" type="number" /></div><div class="field"><label>بيد من</label><select id="fHolder"><option>مصطفى</option><option>سعد</option><option>خالد</option><option>الشيخ محمد</option><option>أحمد</option></select></div><div class="field span-2"><label>البيان</label><input id="fDesc" /></div><div class="field full"><label>ملاحظات</label><textarea id="fNote"></textarea></div></div>`,w=>{const cid=w.querySelector('#fCompany').value;const _in=num(w.querySelector('#fIncome').value),_out=num(w.querySelector('#fExpense').value);if(!w.querySelector('#fDate').value||(_in>0)===(_out>0)||_in<0||_out<0){alert('أدخل التاريخ وقيمة واحدة فقط: إيراد أو منصرف');return false}const x={id:uid('CASH'),companyId:cid,date:w.querySelector('#fDate').value,category:w.querySelector('#fCategory').value,income:num(w.querySelector('#fIncome').value),expense:num(w.querySelector('#fExpense').value),balance:0,holder:w.querySelector('#fHolder').value,description:w.querySelector('#fDesc').value,note:w.querySelector('#fNote').value};state.cash.push(x);recalcCashBalances(cid);audit('إضافة حركة خزينة',{companyId:cid,category:x.category});saveState();render();return true})}
function addTransfer(){openModal('تحويل بين الشركتين',`<div class="field-grid"><div class="field"><label>من</label><select id="fFrom">${state.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>إلى</label><select id="fTo">${state.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>التاريخ</label><input id="fDate" type="date" value="${today()}" /></div><div class="field"><label>المبلغ</label><input id="fAmount" type="number" /></div><div class="field full"><label>البيان</label><input id="fDesc" value="تحويل بين الشركات" /></div></div>`,w=>{const from=w.querySelector('#fFrom').value,to=w.querySelector('#fTo').value;if(from===to||num(w.querySelector('#fAmount').value)<=0)return false;const tr={id:uid('TR'),date:w.querySelector('#fDate').value,fromCompanyId:from,toCompanyId:to,amount:num(w.querySelector('#fAmount').value),description:w.querySelector('#fDesc').value};state.transfers.push(tr);state.cash.push({id:uid('CASH'),companyId:from,date:tr.date,category:'تحويل بين الشركات',income:0,expense:tr.amount,balance:0,holder:'',description:tr.description,ref:tr.id,note:''});state.cash.push({id:uid('CASH'),companyId:to,date:tr.date,category:'تحويل بين الشركات',income:tr.amount,expense:0,balance:0,holder:'',description:tr.description,ref:tr.id,note:''});recalcCashBalances(from);recalcCashBalances(to);audit('تحويل بين الشركات',tr);saveState();render();return true})}
function savePayroll(mk){const old=state.payroll[mk]||{items:{}};const items={...(old.items||{})};empsForMonth(mk,currentCompany).forEach(e=>{const r=calcPayroll(e,mk);items[e.id]={...(items[e.id]||{}),allowance:r.allowance,bonus:r.bonus,deduction:r.deduction,paid:r.paid}});const all=empsForMonth(mk,'all').map(e=>calcPayroll(e,mk));state.payroll[mk]={...old,items,netTotal:all.reduce((t,r)=>t+r.net,0),grossTotal:all.reduce((t,r)=>t+r.gross,0),approvedAt:new Date().toISOString()};audit('اعتماد مرتبات',{month:mk});saveState();showToast('تم اعتماد كشف المرتبات');render()}
function togglePayrollPaid(eid,mk){const emp=state.employees.find(e=>e.id===eid);if(!emp)return;state.payroll[mk]??={items:{}};state.payroll[mk].items??={};const item=state.payroll[mk].items[eid]??={};const ref=`PAY-${mk}-${eid}`;
 if(!item.paid){const p=calcPayroll(emp,mk);let toDeduct=Math.min(p.loan,Math.max(0,p.gross-p.deduction));const alloc=[],rolled=[],nk=nextMonthKey(mk);
  state.loans.filter(l=>l.employeeId===eid&&l.month===mk&&num(l.amount)-num(l.repaid)>0).sort((a,b)=>String(a.date).localeCompare(String(b.date))).forEach(l=>{const rem=num(l.amount)-num(l.repaid);const take=Math.min(rem,toDeduct);if(take>0){l.repaid=num(l.repaid)+take;toDeduct-=take;alloc.push({id:l.id,amt:take})}if(num(l.amount)-num(l.repaid)>0){rolled.push({id:l.id,from:l.month});l.month=nk}});
  const {employee,paid,...snap}=p;item.snapshot=snap;item.alloc=alloc;item.rolled=rolled;item.paid=true;
  if(p.net>0&&!state.cash.some(x=>x.ref===ref))state.cash.push({id:uid('CASH'),companyId:emp.companyId,date:today(),category:'مرتبات',income:0,expense:p.net,balance:0,holder:'',description:`صرف مرتب ${emp.name} - ${mk}`,ref,note:''});
 }else{(item.alloc||[]).forEach(a=>{const l=state.loans.find(x=>x.id===a.id);if(l)l.repaid=Math.max(0,num(l.repaid)-a.amt)});(item.rolled||[]).forEach(r=>{const l=state.loans.find(x=>x.id===r.id);if(l)l.month=r.from});delete item.snapshot;item.alloc=[];item.rolled=[];item.paid=false;state.cash=state.cash.filter(x=>x.ref!==ref)}
 recalcCashBalances(emp.companyId);audit('تغيير حالة صرف المرتب',{employeeId:eid,month:mk,paid:item.paid});saveState();render()}
function addPartnerPayment(companyId){const co=state.companies.find(x=>x.id===companyId);const cm=sel.settle?{y:+sel.settle.split('-')[0],m:+sel.settle.split('-')[1]}:currentMonth();openModal(`دفع شريك — ${esc(co.name)}`,`<div class="field-grid"><div class="field"><label>الشريك</label><select id="fPartner">${(co.partners||[]).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>المبلغ</label><input id="fAmount" type="number" /></div><div class="field"><label>الشهر</label><input id="fMonth" type="month" value="${monthKey(cm.y,cm.m)}" /></div><div class="field full"><label>ملاحظة</label><textarea id="fNote"></textarea></div></div>`,w=>{const pid=w.querySelector('#fPartner').value;if(!pid||num(w.querySelector('#fAmount').value)<=0)return false;const amount=num(w.querySelector('#fAmount').value);const date=today();const payment={id:uid('PP'),companyId,partnerId:pid,amount,month:w.querySelector('#fMonth').value,date,note:w.querySelector('#fNote').value};state.partnerPayments.push(payment);const partner=co.partners.find(p=>p.id===pid);state.cash.push({id:uid('CASH'),companyId,date,category:'شركاء',income:0,expense:amount,balance:0,holder:'',description:`دفع شريك ${partner?.name||''}`,ref:payment.id,note:payment.note});recalcCashBalances(companyId);audit('دفع شريك',{companyId,partnerId:pid});saveState();render();return true})}

function backup(){if(!Auth.can('backup')){showToast('النسخ الاحتياطي غير متاح لصلاحيتك');return}state.settings.lastBackupAt=new Date().toISOString();audit('إنشاء نسخة احتياطية');saveState();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`amanah_backup_${today()}.json`;a.click();URL.revokeObjectURL(a.href);showToast('تم تنزيل النسخة الاحتياطية')}
function restore(e){if(!Auth.can('restore')){e.target.value='';alert('الاسترجاع للمدير فقط');return}const file=e.target.files?.[0];if(!file)return;e.target.value='';const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);if(!Array.isArray(parsed.companies)||!Array.isArray(parsed.employees))return alert('الملف غير صالح');if(!confirm('سيتم استبدال البيانات الحالية (ستُنزَّل نسخة من البيانات الحالية أولًا). هل تريد المتابعة؟'))return;download(`amanah_before_restore_${today()}.json`,JSON.stringify(state,null,2),'application/json');state=normalizeState(parsed);refreshCompanyFilter();audit('استعادة نسخة');saveState({restore:true});render();showToast('تم استرجاع النسخة')}catch(err){alert('تعذر قراءة النسخة')}};reader.readAsText(file)}

function download(filename,content,mime){const blob=new Blob([mime.startsWith('text/csv')?'\uFEFF'+content:content],{type:mime});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href)}
const LOGO=typeof LOGO_DATA!=='undefined'?LOGO_DATA:'logo.png';
const logoHead=()=>`<table style="border:0;width:auto;margin:0"><tr><td style="border:0;padding:0 0 0 14px"><img src="${LOGO}" width="96" alt=""></td><td style="border:0;padding:0"><h1 style="margin:0">${esc(state.settings.organization)}</h1></td></tr></table>`;
function reportShell(title,body){return `<html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>${esc(title)}</title><style>@page{size:A4 landscape;margin:12mm}body{font-family:Arial,Tahoma,sans-serif;padding:20px}h1{margin:0;color:#b8860b}table{border-collapse:collapse;width:100%;margin:10px 0}th,td{border:1px solid #999;padding:5px;text-align:right}th{background:#111;color:#fff}tfoot td{font-weight:bold;background:#f3f3f3}</style></head><body>${logoHead()}<h2>${esc(title)}</h2>${body}</body></html>`}
function rn(v){return Number(v||0).toLocaleString('en-US',{maximumFractionDigits:2})}
function reportPayroll(mode){return payrollOut(mode,document.getElementById('repMonth').value,document.getElementById('repCompany').value)}
function payrollOut(mode,m,co){if(!m)return alert('اختر الشهر');const rows=empsForMonth(m,co).map(e=>calcPayroll(e,m));const title=`كشف مرتبات ${m}`;const tot=k=>rows.reduce((t,r)=>t+num(r[k]),0);
 if(mode==='csv')return download(`كشف_مرتبات_${m}.csv`,['الموظف,الشركة,الأيام,قيمة اليوم,الأساسي,البدلات,الحوافز,الإجمالي,السلف,الخصومات,الصافي',...rows.map(r=>[r.employee.name,companyName(r.employee.companyId),r.days,r.daily,r.basic,r.allowance,r.bonus,r.gross,r.loan,r.deduction,r.net].map(csvCell).join(',')),['الإجمالي','','','',tot('basic'),tot('allowance'),tot('bonus'),tot('gross'),tot('loan'),tot('deduction'),tot('net')].map(csvCell).join(',')].join('\n'),'text/csv;charset=utf-8');
 const html=reportShell(title,`<table><thead><tr><th>الموظف</th><th>الشركة</th><th>الأيام</th><th>قيمة اليوم</th><th>الأساسي</th><th>بدلات</th><th>حوافز</th><th>الإجمالي</th><th>السلف</th><th>خصومات</th><th>الصافي</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.employee.name)}</td><td>${esc(companyName(r.employee.companyId))}</td><td>${r.days}</td><td>${rn(r.daily)}</td><td>${rn(r.basic)}</td><td>${rn(r.allowance)}</td><td>${rn(r.bonus)}</td><td>${rn(r.gross)}</td><td>${rn(r.loan)}</td><td>${rn(r.deduction)}</td><td>${rn(r.net)}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="4">الإجمالي</td><td>${rn(tot('basic'))}</td><td>${rn(tot('allowance'))}</td><td>${rn(tot('bonus'))}</td><td>${rn(tot('gross'))}</td><td>${rn(tot('loan'))}</td><td>${rn(tot('deduction'))}</td><td>${rn(tot('net'))}</td></tr></tfoot></table>`);
 if(mode==='print')return printHtml(html);return download(`كشف_مرتبات_${m}.doc`,html,'application/msword')}
function reportSettlement(mode){const m=document.getElementById('repSettleMonth').value;if(!m)return alert('اختر الشهر');const [y,mo]=m.split('-').map(Number);const cm={y,m:mo};const rows=state.companies.map(co=>({...calcSummary(co.id,cm),co}));
 const prt=rows.flatMap(r=>(r.co.partners||[]).map(p=>({co:r.co.name,name:p.name,rate:num(p.rate),...partnerDue(r.co,p,r,m)})));
 if(mode==='csv')return download(`تسوية_${m}.csv`,['الشركة,الإيراد,الضريبة,صافي الإيراد,التكلفة,صافي الربح',...rows.map(r=>[r.co.name,r.revenue,r.tax,r.netRevenue,r.cost,r.profit].map(csvCell).join(',')),'','الشركة,الشريك,النسبة %,نصيب النسبة,مبلغ إضافي/خصم,المستحق,المدفوع,المتبقي',...prt.map(p=>[p.co,p.name,p.rate,p.share,p.adj,p.due,p.paid,p.rest].map(csvCell).join(','))].join('\n'),'text/csv;charset=utf-8');
 const html=reportShell(`التسوية الشهرية ${m}`,`<table><thead><tr><th>الشركة</th><th>الإيراد</th><th>الضريبة</th><th>صافي الإيراد</th><th>التكلفة</th><th>صافي الربح</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.co.name)}${r.estimated?' (إيراد تقديري)':''}</td><td>${rn(r.revenue)}</td><td>${rn(r.tax)}</td><td>${rn(r.netRevenue)}</td><td>${rn(r.cost)}</td><td>${rn(r.profit)}</td></tr>`).join('')}</tbody></table><h3>نصيب الشركاء</h3><table><thead><tr><th>الشركة</th><th>الشريك</th><th>النسبة</th><th>نصيب النسبة</th><th>مبلغ إضافي/خصم</th><th>المستحق</th><th>المدفوع</th><th>المتبقي</th></tr></thead><tbody>${prt.map(p=>`<tr><td>${esc(p.co)}</td><td>${esc(p.name)}</td><td>${p.rate}%</td><td>${rn(p.share)}</td><td>${rn(p.adj)}</td><td>${rn(p.due)}</td><td>${rn(p.paid)}</td><td>${rn(p.rest)}</td></tr>`).join('')||'<tr><td colspan="8">لا يوجد شركاء</td></tr>'}</tbody></table>`);
 if(mode==='print')return printHtml(html);return download(`تسوية_${m}.doc`,html,'application/msword')}

function reportCash(mode){const g=id=>document.getElementById(id);const co=(g('repCashCompany')&&g('repCashCompany').value)||(currentCompany!=='all'?currentCompany:state.companies[0].id);const from=(g('repCashFrom')&&g('repCashFrom').value)||'',to=(g('repCashTo')&&g('repCashTo').value)||'';const company=state.companies.find(c=>c.id===co);if(!company)return alert('اختر الشركة');
 const all=state.cash.filter(x=>x.companyId===co).sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.id).localeCompare(String(b.id)));const fromD=from?from+'-01':'',toD=to?to+'-31':'';
 const opening=fromD?all.filter(x=>x.date<fromD).reduce((t,x)=>t+num(x.income)-num(x.expense),0):0;const rows=all.filter(x=>(!fromD||x.date>=fromD)&&(!toD||x.date<=toD));let bal=opening;const lines=rows.map(x=>{bal+=num(x.income)-num(x.expense);return {...x,run:bal}});
 const inc=rows.reduce((t,x)=>t+num(x.income),0),out=rows.reduce((t,x)=>t+num(x.expense),0);const cats={};rows.forEach(x=>{const k=x.category||'أخرى';cats[k]=cats[k]||{inc:0,out:0};cats[k].inc+=num(x.income);cats[k].out+=num(x.expense)});
 const period=`${from||'البداية'} إلى ${to||'الآن'}`;const title=`تقرير خزينة ${company.name}`;
 if(mode==='csv')return download(`خزينة_${company.name}.csv`,[`${title} (${period})`,'التاريخ,البيان,البند,الإيراد,المنصرف,الرصيد,بيد من,ملاحظات',['','رصيد أول المدة','',0,0,opening,'',''].map(csvCell).join(','),...lines.map(x=>[x.date,x.description,x.category,x.income,x.expense,x.run,x.holder,x.note].map(csvCell).join(',')),['','الإجمالي','',inc,out,bal,'',''].map(csvCell).join(',')].join('\n'),'text/csv;charset=utf-8');
 const html=reportShell(title,`<p>الفترة: ${esc(period)}</p><table><thead><tr><th>رصيد أول المدة</th><th>إجمالي الإيرادات</th><th>إجمالي المنصرف</th><th>الرصيد الحالي</th></tr></thead><tbody><tr><td>${rn(opening)}</td><td>${rn(inc)}</td><td>${rn(out)}</td><td>${rn(bal)}</td></tr></tbody></table><h3>ملخص حسب البند</h3><table><thead><tr><th>البند</th><th>الإيراد</th><th>المنصرف</th></tr></thead><tbody>${Object.entries(cats).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${rn(v.inc)}</td><td>${rn(v.out)}</td></tr>`).join('')||'<tr><td colspan="3">لا توجد حركات</td></tr>'}</tbody></table><h3>الحركات</h3><table><thead><tr><th>التاريخ</th><th>البيان</th><th>البند</th><th>الإيراد</th><th>المنصرف</th><th>الرصيد</th><th>بيد من</th></tr></thead><tbody><tr><td colspan="5">رصيد أول المدة</td><td>${rn(opening)}</td><td></td></tr>${lines.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.description)}</td><td>${esc(x.category)}</td><td>${rn(x.income)}</td><td>${rn(x.expense)}</td><td>${rn(x.run)}</td><td>${esc(x.holder||'')}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="3">الإجمالي</td><td>${rn(inc)}</td><td>${rn(out)}</td><td>${rn(bal)}</td><td></td></tr></tfoot></table>`);
 if(mode==='print')return printHtml(html);return download(`خزينة_${company.name}.doc`,html,'application/msword')}

function csvCell(v){const s=String(v??'');return `"${s.replace(/"/g,'""')}"`}
function printHtml(html){const w=window.open('','_blank');if(!w){alert('اسمح بالنوافذ المنبثقة لطباعة التقرير');return}w.document.write(html);w.document.close();setTimeout(()=>w.print(),300)}

init();
Auth.init({login:async(u,info)=>{const resumed=Boolean(info&&info.resumed);buildNav();refreshCompanyFilter();if(!resumed)currentRoute='dashboard';const ok=await reloadFromServer();if(ok&&!resumed){audit('تسجيل دخول');saveState()}startPolling()},logout:()=>{stopPolling();state=normalizeState({});serverRev=0;dirty=false;lastSnap='';pendingAudit=[];document.getElementById('content').innerHTML='';document.getElementById('userBox').innerHTML='';document.getElementById('nav').innerHTML='';setSync('','')}});

/* ===== المستخدمون وكلمة المرور ===== */
const roleOpts=sel0=>Object.entries(Auth.ROLES).map(([k,v])=>`<option value="${k}" ${k===sel0?'selected':''}>${v}</option>`).join('');
async function renderUsers(c){const users=await Auth.refreshUsers();const me=Auth.current();
 c.innerHTML=`<div class="section-toolbar"><div><h3>المستخدمون</h3><div class="muted">المدير: كل شيء + المستخدمون + الاسترجاع. المحاسب: إدخال وتعديل + نسخ احتياطي. المشاهدة: عرض وتقارير فقط.</div></div><div class="toolbar-right"><button class="btn primary" data-action="add-user">+ مستخدم</button></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>اسم المستخدم</th><th>الدور</th><th>الحالة</th><th>آخر دخول</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}${u.id===me.id?' <span class="pill blue">أنت</span>':''}</td><td dir="ltr">${esc(u.username)}</td><td>${esc(Auth.ROLES[u.role]||u.role)}</td><td>${u.active?'<span class="pill green">نشط</span>':'<span class="pill gray">موقوف</span>'}</td><td>${u.lastLogin?new Date(u.lastLogin).toLocaleString('ar-EG'):'—'}</td><td><button class="btn small ghost" data-action="edit-user" data-id="${u.id}">تعديل</button> ${u.id===me.id?'':`<button class="btn small danger" data-action="delete-user" data-id="${u.id}">حذف</button>`}</td></tr>`).join('')}</tbody></table></div></div>`}
function addUserModal(){openModal('إضافة مستخدم',`<div class="field-grid"><div class="field"><label>الاسم</label><input id="uName" /></div><div class="field"><label>اسم المستخدم</label><input id="uUser" dir="ltr" /></div><div class="field"><label>كلمة المرور</label><input id="uPass" type="password" dir="ltr" /></div><div class="field"><label>الدور</label><select id="uRole">${roleOpts('accountant')}</select></div></div>`,w=>{(async()=>{const r=await Auth.addUser({name:w.querySelector('#uName').value,username:w.querySelector('#uUser').value,password:w.querySelector('#uPass').value,role:w.querySelector('#uRole').value});if(!r.ok)return alert(r.msg);w.remove();audit('إضافة مستخدم',{username:w.querySelector('#uUser').value.trim().toLowerCase()});saveState();render();showToast('تمت إضافة المستخدم')})()},{force:true})}
function editUserModal(id){const u=Auth.list().find(x=>x.id===id);if(!u)return;openModal(`تعديل ${esc(u.name)}`,`<div class="field-grid"><div class="field"><label>الاسم</label><input id="uName" value="${esc(u.name)}" /></div><div class="field"><label>الدور</label><select id="uRole">${roleOpts(u.role)}</select></div><div class="field"><label>الحالة</label><select id="uActive"><option value="1" ${u.active?'selected':''}>نشط</option><option value="0" ${u.active?'':'selected'}>موقوف</option></select></div><div class="field"><label>كلمة مرور جديدة (اتركها فارغة للإبقاء)</label><input id="uPass" type="password" dir="ltr" /></div></div>`,w=>{(async()=>{const r=await Auth.updateUser(id,{name:w.querySelector('#uName').value,role:w.querySelector('#uRole').value,active:w.querySelector('#uActive').value==='1',password:w.querySelector('#uPass').value||undefined});if(!r.ok)return alert(r.msg);w.remove();audit('تعديل مستخدم',{username:u.username});saveState();render();showToast('تم الحفظ')})()},{force:true})}
async function deleteUserAction(id){const u=Auth.list().find(x=>x.id===id);if(!u||!confirm(`حذف المستخدم ${u.name}؟`))return;const r=await Auth.deleteUser(id);if(!r.ok)return alert(r.msg);audit('حذف مستخدم',{username:u.username});saveState();render()}
function changePasswordModal(){openModal('تغيير كلمة المرور',`<div class="field-grid"><div class="field full"><label>كلمة المرور الحالية</label><input id="pOld" type="password" dir="ltr" /></div><div class="field"><label>الجديدة</label><input id="pNew" type="password" dir="ltr" /></div><div class="field"><label>تأكيد الجديدة</label><input id="pNew2" type="password" dir="ltr" /></div></div>`,w=>{(async()=>{if(w.querySelector('#pNew').value!==w.querySelector('#pNew2').value)return alert('تأكيد كلمة المرور غير مطابق');const r=await Auth.changeOwnPassword(w.querySelector('#pOld').value,w.querySelector('#pNew').value);if(!r.ok)return alert(r.msg);w.remove();audit('تغيير كلمة المرور');saveState();showToast('تم تغيير كلمة المرور')})()},{force:true})}
